const togglePub = () => {
  if (!canPub || pubBusy) return;
  setPubBusy(true);
  // v4.8: 同步异常也折进 promise —— 防止未来 togglePublic 出现同步 throw 把 pubBusy 永久钉死。
  var p;
  try { p = Promise.resolve(window.__SP_LOBBY.togglePublic(code)); }
  catch (e) { p = Promise.resolve({ ok: false, text: '操作失败' }); }
  p.then((r) => {
    setPubBusy(false);
    if (r && r.ok) { setPub(!!r.isPublic); setPubNote(String(r.text || '')); }
    else { setPubNote(String((r && r.text) || '操作失败')); }
  }).catch(() => { setPubBusy(false); setPubNote('操作失败'); });
};
